import java.util.*;

class Solution {
    public List<String> signExpressions(String num, int target) {
        List<String> out = new ArrayList<>();
        go(num, target, 0, "", 0L, 0L, out);
        return out;
    }

    private void go(String num, long target, int pos, String expr, long value, long last, List<String> out) {
        if (pos == num.length()) {
            if (value == target) out.add(expr);
            return;
        }
        for (int i = pos; i < num.length(); i++) {
            if (i > pos && num.charAt(pos) == '0') break;          // no leading zeros
            String part = num.substring(pos, i + 1);
            long cur = Long.parseLong(part);
            if (pos == 0) {
                go(num, target, i + 1, part, cur, cur, out);        // first number
            } else {
                go(num, target, i + 1, expr + "+" + part, value + cur, cur, out);
                go(num, target, i + 1, expr + "-" + part, value - cur, -cur, out);
                go(num, target, i + 1, expr + "*" + part, value - last + last * cur, last * cur, out);
            }
        }
    }
}

