class Solution:
    def signExpressions(self, num: str, target: int) -> List[str]:
        out = []
        def go(i, expr, val, last):
            if i == len(num):
                if val == target: out.append(expr)
                return
            for j in range(i + 1, len(num) + 1):
                s = num[i:j]
                if len(s) > 1 and s[0] == "0": break
                c = int(s)
                if i == 0: go(j, s, c, c)
                else:
                    go(j, expr + "+" + s, val + c, c)
                    go(j, expr + "-" + s, val - c, -c)
                    go(j, expr + "*" + s, val - last + last * c, last * c)
        go(0, "", 0, 0)
        return out

