function signExpressions(num, target) {
  const out = [], n = num.length;
  function evalExpr(e) { // evaluate with precedence, no eval()
    let total = 0, term = 1, sign = 1, cur = "";
    const toks = e.match(/\d+|[+\-*]/g); let pendingMul = false; term = null;
    for (const t of toks) {
      if (t === "+" || t === "-") { total += sign * term; sign = t === "+" ? 1 : -1; term = null; }
      else if (t === "*") pendingMul = true;
      else { const v = Number(t); term = term === null ? v : term * v; pendingMul = false; }
    }
    return total + sign * term;
  }
  (function go(i, e) {
    if (i === n) { if (evalExpr(e) === target) out.push(e); return; }
    const d = num[i];
    if (i === 0) { go(1, d); return; }
    const prev = e[e.length - 1]; // glue only if current number doesn't start with 0
    let k = e.length - 1; while (k >= 0 && /\d/.test(e[k])) k--;
    const curNum = e.slice(k + 1);
    if (!(curNum === "0")) go(i + 1, e + d);
    go(i + 1, e + "+" + d); go(i + 1, e + "-" + d); go(i + 1, e + "*" + d);
  })(0, "");
  return out;
}
